  ('N5-01', 'listening', 1, 5, 'choice', '', '[{"key": "A", "text": "位置不好"}, {"key": "B", "text": "楼层太高"}, {"key": "C", "text": "周围太吵"}, {"key": "D", "text": "价格太贵"}]'::jsonb, 'B', 'auto', 1, '/mock-tests/n5-01/listening.mp3', null, false, array['sk.listening.dialogue']::text[], '«就是太高了，在二十八层» — 28 давхарт, хэт өндөр. «就是» дутагдлыг заана.', 134.1, 154.1, '女：这套房子位置不错，就是太高了，在二十八层。
