  ('N5-01', 'listening', 1, 8, 'choice', '', '[{"key": "A", "text": "比较准时"}, {"key": "B", "text": "票价便宜"}, {"key": "C", "text": "座位舒服"}, {"key": "D", "text": "离家近"}]'::jsonb, 'A', 'auto', 1, '/mock-tests/n5-01/listening.mp3', null, false, array['sk.listening.dialogue']::text[], '«高铁很少晚点», «我最怕飞机晚点» — хурдны галт тэрэг цагтаа явдаг.', 225.5, 250.4, '男：这次去西安出差，你坐高铁还是飞机？
